  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('b6529e5d-622d-5462-b536-2de2d9d66371', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'Which choice completes the text with the most logical and precise word or phrase?', '["reacts to", "helps with", "varies from", "argues with"]'::jsonb, 1, 'Lima beans were domesticated in South America. Their physical structure is no longer identical to the structure of the wild plant they are descended from. Summer squash also _____ its wild ancestor. That ancestor plant had a hard rind and bitter flesh. Indigenous people in eastern North America carefully bred the crop until it had a soft rind and mild-tasting flesh.'),
  ('3c76b183-3de8-5da6-ac30-d731c9e2c407', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'Which choice completes the text with the most logical and precise word or phrase?', '["loses", "purchases", "suspects", "suggests"]'::jsonb, 2, '“Eyes of Zapata” is an English-language short story by Sandra Cisneros. It occasionally includes Spanish words and phrases. The English text surrounding these words and phrases _____ their meaning, so readers who aren’t familiar with Spanish can easily read the story. Ana Castillo takes the same approach in her novel So Far from God.'),
  ('b215b940-0f78-53d6-914a-a406b19f5da6', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'As used in the text, what does the word “demonstrated” most nearly mean?', '["Defined", "Exhibited", "Confirmed", "Protested"]'::jsonb, 3, 'The following text is from Billie Jean King’s 2021 autobiography All In.

People on both sides of my family had repeatedly <u>demonstrated</u> an independent streak. In the end, that was the temperament I gravitated toward, too. Both the Moffitts and the members of my mother’s clan, the Jermans, came from mining and oil-geyser towns on the western frontier. They kept their heads down and worked, worked, worked. But they also bucked convention.'),
  ('5d69c8b7-4dcc-582d-b610-701e02c3d041', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'Which choice completes the text with the most logical and precise word or phrase?', '["reuse", "supply", "imitation", "examination"]'::jsonb, 4, 'Scientists studying marine ecosystems were surprised by the extent of internal carbon recycling by red coralline algae. While some ____ of carbon was expected, the scientists found that the algae reabsorb nearly 40% of the carbon dioxide they produce during calcification processes and harness it for photosynthesis.'),
  ('5f73780e-0c0c-51c8-bf19-408d9c6fbb9a', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'Which choice completes the text with the most logical and precise word or phrase?', '["novelty", "obscurity", "rigor", "shallowness"]'::jsonb, 5, 'The dinosaur displays at museums such as the American Museum of Natural History in New York (which has a mounted Allosaurus fragilis skeleton among its holdings) are notable for the _____ of the research behind them—the museum staff consulted numerous sources to ensure the accuracy of the displays.'),
  ('e564408a-24e4-5dfc-9e3f-e9a4c79770c5', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'Which choice best states the main purpose of the text?', '["The text describes the benefits of being an artist.", "The text argues against placing works of art outside.", "The text describes the popularity of art galleries in the 1960s.", "The text provides information about the land art movement."]'::jsonb, 6, 'The Nazca lines in Peru are designs marked in the earth by ancient peoples. Monuments like these were an inspiration for the land art movement that began in the 1960s. Land art artists create works set in the outdoors. For example, in his 1968 work Annual Rings, Dennis Oppenheim fashioned concentric lines that look like tree rings into the ice that covered a waterway.'),
  ('7e647d14-7a89-5d59-a582-62ea440301d7', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'Which choice best states the main purpose of the text?', '["To summarize how Chloé Zhao’s style of filmmaking changed over the course of her career", "To discuss how Chloé Zhao’s background in documentary filmmaking has influenced her storytelling style in films", "To argue that Chloé Zhao’s films are best understood as documentaries", "To emphasize that Chloé Zhao’s decisions during the filmmaking process reinforce the themes of her films"]'::jsonb, 7, 'Though Chloé Zhao’s films are fictional, she incorporates real events into them in a documentary-like style and casts nonprofessional actors who reside in the places that she aims to portray. She also encourages these actors, whether they are teenagers living on the Pine Ridge Indian Reservation or adults who travel the country for work, to put as much of themselves into their roles as possible. Her approach adds powerful resonance to films that explore the highly personal experiences of place and home, and often the difficult decision to stay or leave.'),
  ('cc29ff70-c438-5d9c-b4c7-f99d4d63f9af', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'Which choice best describes the overall structure of the text?', '["It presents an ongoing environmental challenge, demonstrates why the impact of that challenge may intensify over time, and then criticizes a misguidedly narrow attempt to address that impact.", "It describes a widely accepted approach to addressing an environmental issue caused by a type of chemical emissions, indicates a potential disadvantage of that approach, and then discusses an implication of that disadvantage.", "It reports on a predicament resulting from emissions of a particular greenhouse gas, outlines a strategy aimed at solving that predicament, and then admonishes those who utilize that strategy without fully comprehending its ramifications.", "It suggests an approach aimed at improving a process that reduces emissions associated with a type of air pollutant, highlights an unintended consequence of that approach, and then proposes a strategy to minimize that consequence."]'::jsonb, 8, 'While many initiatives aimed at limiting atmospheric warming focus on curbing emissions of methane (CH4), a greenhouse gas that is typically generated by microbially mediated processes, Lisa Y. Stein and

Mary E. Lidstrom caution that under certain circumstances, such efforts cause microbial communities to accelerate production of nitrous oxide (N2O), another potent greenhouse gas, thus offsetting the

impact of CH4 reduction. Researchers, therefore, need to take such biological interactions into account

to ensure that any CH4 mitigation strategy has an overall positive climate effect.'),
  ('c0988b99-dcf4-5263-bb90-cb58cf3beb1d', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'Which choice best states the main topic of the text?', '["Debut novels", "Famous literary critics", "The benefits of reading", "Careers in the publishing industry"]'::jsonb, 9, 'A debut novel is the first book that an author has published. An example of a debut novel is Freak the Mighty by Rodman Philbrick. It was published in 1993. Debut novels are especially interesting to literary critics and readers because these books offer a look at new voices in the literary world.'),
  ('73739193-bf99-536c-acc4-ce6f71bf077a', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'Which choice best states the main idea of the text?', '["Clara Peeters was an important figure in the development of still-life painting.", "Clara Peeters made significant contributions to multiple genres of painting.", "Clara Peeters introduced the term “still-life painting” to Western Europe.", "Some paintings attributed to Clara Peeters may have been painted by other artists in her circle."]'::jsonb, 10, 'Seventeenth-century Flemish artist Clara Peeters played a crucial role in the history of still-life painting. At a time when historical paintings were the preferred genre—indeed, at a time when there wasn’t even a term for still-life painting in Peeters’s language—Peeters painted food, flowers, fish, and game. Her influence spread throughout Western Europe and she became so strongly associated with the genre that painters who took up similar subjects were sometimes described as belonging to the “circle of Peeters.”'),
  ('b1e18a8f-e5cf-563b-b5ec-0d1846b1520b', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'Which quotation from Great Expectations most effectively illustrates the claim?', '["“In his working-clothes, Joe was a well-knit characteristic-looking blacksmith; in his holiday clothes, he was more like a scarecrow in good circumstances, than anything else.”", "“When I looked back at Joe in the long passage, he was still weighing his hat with the greatest care, and was coming after us in long strides on the tips of his toes.”", "“There I stood, for minutes, looking at Joe, already at work with a glow of health and strength upon his face that made it show as if the bright sun of the life in store for him were shining on it.”", "“Joe!” he said, “You’re going to write a letter now, and tell all about it, and let everybody know how well I’m doing!”"]'::jsonb, 11, 'Great Expectations is an 1861 novel by Charles Dickens. The narrator describes his uncle, Joe Gargery, as being both powerful and tender:'),
  ('cde8cc83-af67-5778-afc9-5ffd2d98b636', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'Which choice most logically completes the text?', '["acorns were only consumed during seasons when tannins were naturally low.", "the bitter taste of tannins was actually a preferred flavor profile in their cuisine.", "the nutritional value of acorns justified the extensive labor required to make them safe to eat.", "leaching acorns in streambed mud was a much more efficient method than grinding them into meal."]'::jsonb, 12, 'Acorns were a staple food for many Indigenous communities in what is now California, but the nuts contain high concentrations of tannins, which are bitter and potentially toxic. To make acorns edible, people developed various leaching processes to remove the tannins. For example, some communities would place whole acorns in the mud of a streambed for several months, while others would grind the acorns into a fine meal and then pour water over it repeatedly. These processes suggest that for these communities, _____'),
  ('ff76bf37-1c17-5423-a09e-bec90ce99184', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'Which statement, if true, would most strongly support the underlined claim?', '["When apes made mouth-touching gestures, which participants tended to correctly interpret as requests for food, the food was visible in the videos.", "Participants correctly identified gestures at the same rate for videos in which the apes made sounds in addition to gestures and videos in which the apes were silent.", "Participants correctly interpreted ape gestures more than 50 percent of the time, whereas they would have only identified gestures correctly 25 percent of the time if they had been guessing.", "Participants reported that they found it easier to interpret gestures when videos were accompanied by sounds of the apes vocalizing."]'::jsonb, 13, 'Researchers have identified over eighty gestures made by nonhuman great apes, such as raising an arm and rocking from side to side, that appear to convey information and that seem to be biologically inherited. Kirsty E. Graham and Catherine Hobaiter hypothesized that humans may be able to interpret great ape gestures, either through an evolutionary inheritance or as part of more general human cognitive abilities. The researchers tested this hypothesis by enlisting participants in an online game in which they had to correctly identify the meanings of ape gestures seen in videos. <u>Though participants</u> <u>achieved some success, it is unclear whether they sometimes did so by making use of additional context</u> <u>provided by the images or sounds in the video recordings.</u>'),
  ('ccde83d3-af5c-5f42-bc7c-06b1d718c8d4', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'Which choice most logically completes the text?', '["the lower the temperature must be to fry the food.", "the softer the crust will be when frying is completed.", "the higher the fat content will be when frying is completed.", "the quicker the crust will lose its permeability."]'::jsonb, 14, 'Biochemists I. Sam Saguy and Eli J. Pinthus studied the mass and heat transfer processes that occur when foods, such as the Indian snacks batata vada and sabudana vada, are fried in oil. During frying, water in the crust evaporates, leaving voids that oil can fill, thereby increasing the food’s fat content. As the process continues, water from the food’s center moves to the crust as long as the crust remains permeable. Therefore, the more moisture a food loses during frying, _____'),
  ('10b4b68e-683c-5a13-98bb-05446cc6a72e', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'Which choice most logically completes the text?', '["were likely already close to extinction long before non-native birds arrived on the island.", "probably established themselves on the island at about the same time as common waxbills and other fruit-eating birds did.", "seem to produce fewer fruits per plant now than they did when fruit-eating birds native to the island were still present.", "may now depend on non-native birds, such as the common waxbill, to help maintain and increase their populations on the island."]'::jsonb, 15, 'The kawau tree is one of many forest plant species native to Oahu (a Hawaiian island) that are at risk of extinction in the wild. Ecologists say that fruit-eating birds help support these species’ population numbers by dropping seeds from the plants’ fruits to different spots where new plants can grow. The birds native to Oahu that used to do this have all gone extinct over time. However, the common waxbill and other fruit-eating bird species brought to the island in the last 150 years have been found to spread plant seeds. Based on this finding, some ecologists suggest that kawau trees and other forest plants native to Oahu ____'),
  ('0954cab4-b585-5697-8453-b1c538f8452a', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["do have something in common?", "do they have something in common.", "do they have something in common?", "do have something in common."]'::jsonb, 16, 'Though they are in different countries, the towns of Entebbe, Uganda, and Booue, Gabon, _____ They are among the rare places that sit almost directly on the equator.'),
  ('ef123307-1e91-5fcc-a946-dbdc40b57dc0', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["being", "are", "is", "were"]'::jsonb, 17, 'Pumpkins were among the many plant species from the Western Hemisphere introduced into the Eastern Hemisphere in the years following Christopher Columbus’s first transatlantic voyage in 1492. This ongoing transfer of species between hemispheres _____ now known as the Columbian Exchange.'),
  ('779d56c2-b06e-59a1-8943-5f0188cff7f5', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["have been", "are", "is", "were"]'::jsonb, 18, 'Among several noun cases used in Sanskrit and other Indo-Aryan languages _____ the locative case, used to indicate that an action is occurring in, at, on, or near a particular noun.'),
  ('84c3f752-e7d4-5f49-a509-3fd462696555', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["ancestor; mexicana, a", "ancestor: mexicana, a", "ancestor mexicana a", "ancestor, mexicana. A"]'::jsonb, 19, 'It was long thought that maize was domesticated solely from parviglumis—a subspecies of teosinte, a wild grass—in Mexico’s lowlands about 9,000 years ago. However, a 2024 analysis has revealed that between 15 and 25 percent of maize’s genes can be traced to a second _____ highland subspecies of teosinte that was hybridized with maize around 4,000 years after the initial domestication.'),
  ('52afc1f4-1ead-5800-8b4a-fff38ccaed1f', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["mediated,", "mediated", "mediated:", "mediated and"]'::jsonb, 20, 'Hummingbird flower mites use electroreception to detect electric fields created by flapping hummingbird wings, allowing mites to travel from flower to flower in hummingbird beaks. Both host detection and transportation are electrically _____ when mites move their legs toward the arriving hummingbird, they are pulled by electrostatic force to the bird’s modulated electric fields—a process that occurs in milliseconds.'),
  ('de9a3cfd-210a-5799-8c4f-50c86da1aa46', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'Which choice completes the text with the most logical transition?', '["In addition,", "At last,", "For example,", "However,"]'::jsonb, 21, 'The World Cup of men’s soccer, one of the biggest sporting events on the planet, brought 32 national teams from six continents to the host country, Germany, in 2006. The event, which is held every four years, used to be much smaller and more limited geographically. _____ the 1930 World Cup in Uruguay included only 13 teams, all from Europe and the Americas.'),
  ('14cd1224-4d45-50ae-b85f-3939d5571697', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'Which choice completes the text with the most logical transition?', '["By achieving such a lofty goal,", "Beyond the simple coining of a term,", "Despite its creation of such an iconic trope,", "Ultimately limited in its lasting influence,"]'::jsonb, 22, 'Karel Čapek’s 1920 play R.U.R. (Rossum’s Universal Robots), in which artificial workers overthrow their masters, left an indelible mark on the science fiction genre, and the English language, by introducing the term “robot” (derived from the Czech word robota, meaning “indentured labor” or “drudgery”). ______ Čapek’s play also contributed to a venerable literary and mythological tradition: using artificial beings as mirrors and foils for humanity.'),
  ('e908a6b7-523e-50a2-ac82-068108c6dd73', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'The student wants to define the term “epistolary novel.” Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Published in 1747, Letters from a Peruvian Woman is an epistolary novel by French author Françoise de Graffigny.", "Françoise de Graffigny’s novel Letters from a Peruvian Woman was published in 1747 and consists primarily of letters sent between a captured Incan princess and her fiancé.", "Consisting primarily of letters sent between a captured Incan princess and her fiancé, Françoise de Graffigny’s Letters from a Peruvian Woman is an epistolary novel.", "An epistolary novel is a novel written primarily as a series of fictional documents, such as letters, journal entries, or newspaper clippings."]'::jsonb, 23, 'While researching a topic, a student has taken the following notes:

Letters from a Peruvian Woman (1747) is an epistolary novel by French author Françoise de Graffigny. Epistolary novels are novels written primarily as a series of fictional documents.
These documents can be letters, journal entries, newspaper clippings, and more.
Letters from a Peruvian Woman consists primarily of letters.
The letters are sent between a captured Incan princess and her fiancé.'),
  ('e5ef37e2-5514-57b9-b779-6d9971f43629', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'The student wants to emphasize a difference between the two seaweeds. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["While wakame and ma-konbu contain umami flavor, umami can also be found in sardines and mushrooms.", "After tasting two types of brown seaweed, wakame and ma-konbu, participants in a study found ma-konbu’s umami flavor to be the more intense of the two.", "Wakame is a type of brown seaweed, but so is ma-konbu.", "Some types of brown seaweed, like wakame and ma-konbu, trigger umami flavor in human taste buds."]'::jsonb, 24, 'While researching a topic, a student has taken the following notes:

The human tongue contains taste receptors for a rich, savory flavor called umami.
Umami is triggered by the compounds in a variety of foods, including sardines and mushrooms. Participants in a study tasted a sample of wakame, a type of brown seaweed.
They rated its umami intensity as moderate.
The participants tasted a sample of ma-konbu, another type of brown seaweed.
They rated its umami intensity as high.'),
  ('8ca7b820-7040-5fe0-8fef-a13a2c1f17ea', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'The student wants to provide a specific example of an isthmus. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["There is a land bridge in Mexico.", "One example of an isthmus is the Isthmus of Tehuantepec in Mexico.", "An isthmus, also known as a land bridge, is a strip of land that connects two larger pieces of land across an expanse of water.", "In Mexico, the southern tip of Mexico is connected to the northern part of Mexico."]'::jsonb, 25, 'While researching a topic, a student has taken the following notes:

An isthmus is a strip of land that connects two larger pieces of land across an expanse of water. It is also known as a land bridge.
The Isthmus of Tehuantepec is located in Mexico.
It connects the southern tip of Mexico to the northern part of Mexico.'),
  ('0b848629-056c-5c14-8927-c2d590231783', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'The student wants to acknowledge a complication affecting travel through wormholes. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The hypothetical tunnels known as wormholes would be potential shortcuts through spacetime were it not for one complication: they have less energy than empty space.", "Einstein’s theory of general relativity allows for potential spacetime shortcuts called wormholes but does not explain how matter with negative energy density could travel through them.", "For matter to travel through a wormhole, the matter would need to have less energy than empty space; such matter has not been shown to exist.", "A wormhole, a theoretical tunnel through spacetime, would require matter with negative energy density, which has not been detected."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

Albert Einstein’s theory of general relativity allows for potential shortcuts through spacetime. These hypothetical spacetime tunnels are known as wormholes.
For matter to travel through a wormhole, it would need to have negative energy density. Negative energy density means that the matter would have less energy than empty space. Such matter has not been shown to exist.'),
  ('a9d541c4-5552-5857-9c56-06addee749ed', 'b953a47c-c916-533a-b871-dc542dc3b2d5', 'The student wants to describe Shanawdithit’s approach and explain its significance. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Shanawdithit’s maps are part of a broader tradition of Indigenous cartography that, according to Pearce, ranges from “Hawaiian performative cartographies to Navajo verbal maps and sand paintings.”", "Shanawdithit mapped Beothuk Lake through significant encounters that occurred there, an approach that Pearce describes as “depicting space as universal [and] homogenized.”", "By depicting experiences of the Beothuk that occurred around Beothuk Lake, Shanawdithit’s maps reflect Indigenous cartography’s emphasis on “experienced space, or place” rather than the landscape alone.", "Shanawdithit’s work illustrates the diverse nature of Indigenous mapping traditions, such as those described by Pearce, who highlights Hawaiian and Navajo examples."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

Shanawdithit (1801–1829) was a Beothuk cartographer (mapmaker).
Her maps of Newfoundland’s Beothuk Lake outline both the lake and various points around the lake where encounters between the Indigenous Beothuk people and British colonists occurred. Her maps are notable for depicting the experiences the Beothuk had within the landscape. Contemporary Potawatomi cartographer Margaret Pearce: Indigenous cartography emphasizes “experienced space, or place, as opposed to the Western convention of depicting space as universal, homogenized, and devoid of human experience.”
Pearce: “Indigenous cartographies are as diverse as Indigenous cultures, from Hawaiian performative cartographies to Navajo verbal maps and sand paintings.”')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('b6529e5d-622d-5462-b536-2de2d9d66371', 2, null, 'Like lima beans, squash differs from its wild ancestor (hard and bitter vs soft and mild): "varies from."'),
  ('3c76b183-3de8-5da6-ac30-d731c9e2c407', 3, null, 'The surrounding English hints at what the Spanish means, so readers understand it: "suggests."'),
  ('b215b940-0f78-53d6-914a-a406b19f5da6', 1, null, 'Her relatives repeatedly showed an independent streak: "exhibited."'),
  ('5d69c8b7-4dcc-582d-b610-701e02c3d041', 0, null, 'The algae take back their own CO2 and use it again: some "reuse" was expected.'),
  ('5f73780e-0c0c-51c8-bf19-408d9c6fbb9a', 2, null, 'Staff consulted many sources to ensure accuracy: the "rigor" of the research.'),
  ('e564408a-24e4-5dfc-9e3f-e9a4c79770c5', 3, null, 'The text explains what land art is, where it came from, and gives an example.'),
  ('7e647d14-7a89-5d59-a582-62ea440301d7', 3, null, 'Real places, local actors and personal input give "resonance" to films about place and home.'),
  ('cc29ff70-c438-5d9c-b4c7-f99d4d63f9af', 1, null, 'A common approach (cutting methane), a drawback (more N2O), then what researchers must therefore do.'),
  ('c0988b99-dcf4-5263-bb90-cb58cf3beb1d', 0, null, 'The text defines debut novels, gives an example, and says why they interest readers.'),
  ('73739193-bf99-536c-acc4-ce6f71bf077a', 0, null, 'Peeters shaped still-life painting and influenced a "circle" of painters.'),
  ('b1e18a8f-e5cf-563b-b5ec-0d1846b1520b', 1, null, 'Long strides show his size and strength, while tiptoeing and handling his hat "with the greatest care" show gentleness.'),
  ('cde8cc83-af67-5778-afc9-5ffd2d98b636', 2, null, 'Communities spent months or repeated effort leaching acorns, so the food must have been worth the labor.'),
  ('ff76bf37-1c17-5423-a09e-bec90ce99184', 0, null, 'If food was visible whenever apes asked for food, participants could have guessed from the video, not the gesture.'),
  ('ccde83d3-af5c-5f42-bc7c-06b1d718c8d4', 2, null, 'Moisture that leaves the food leaves voids that oil fills, so more moisture lost means more fat.'),
  ('10b4b68e-683c-5a13-98bb-05446cc6a72e', 3, null, 'Native seed-dispersing birds are gone and non-native birds now spread seeds, so the plants may rely on them.'),
  ('0954cab4-b585-5697-8453-b1c538f8452a', 3, null, 'This is a statement, not a question: "do have something in common."'),
  ('ef123307-1e91-5fcc-a946-dbdc40b57dc0', 2, null, 'The singular subject "transfer" takes "is."'),
  ('779d56c2-b06e-59a1-8943-5f0188cff7f5', 2, null, 'The inverted subject is the singular "the locative case": "is."'),
  ('84c3f752-e7d4-5f49-a509-3fd462696555', 1, null, 'A colon introduces the name of the second ancestor; the appositive follows a comma.'),
  ('52afc1f4-1ead-5800-8b4a-fff38ccaed1f', 2, null, 'A colon introduces the explanation of how the process is electrical.'),
  ('de9a3cfd-210a-5799-8c4f-50c86da1aa46', 2, null, 'The 1930 World Cup illustrates how small and limited the event used to be.'),
  ('14cd1224-4d45-50ae-b85f-3939d5571697', 1, null, 'Besides coining "robot," the play contributed to a broader tradition.'),
  ('e908a6b7-523e-50a2-ac82-068108c6dd73', 3, null, 'It defines the term: a novel written as a series of fictional documents.'),
  ('e5ef37e2-5514-57b9-b779-6d9971f43629', 1, null, 'It contrasts the two seaweeds: ma-konbu''s umami was more intense.'),
  ('8ca7b820-7040-5fe0-8fef-a13a2c1f17ea', 1, null, 'It names a specific isthmus: the Isthmus of Tehuantepec.'),
  ('0b848629-056c-5c14-8927-c2d590231783', 2, null, 'Travel needs matter with less energy than empty space, and such matter hasn''t been shown to exist.'),
  ('a9d541c4-5552-5857-9c56-06addee749ed', 2, null, 'It describes her maps of Beothuk experiences and links them to Pearce''s "experienced space."')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

-- PeaklyTest Mar 2026 · Reading & Writing · Module 2
insert into public.tests (id, title, section, description, duration_min, position, published, form_title, module_no)
values ('cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'PeaklyTest Mar 2026 · Reading & Writing · Module 2', 'Reading & Writing', 'Reading & Writing, Module 2 of the Mar 2026 PeaklyTest · 27 questions · 32 minutes', 32, 151, true, 'PeaklyTest Mar 2026 · Reading & Writing', 2)
on conflict (id) do update set title = excluded.title, section = excluded.section, description = excluded.description,
  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('216c48b9-2ee6-547e-a967-70e4ee569e8c', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'Which choice completes the text with the most logical and precise word or phrase?', '["cryptic", "inaccessible", "haughty", "perfunctory"]'::jsonb, 1, 'Although more documentaries are being made than ever before, too many seem _____, offering stories without any depth. In a refreshing contrast, Ahmir “Questlove” Thompson’s 2021 documentary Summer of Soul (...or, When the Revolution Could Not Be Televised) draws from present-day interviews to supply compelling historical and social context for footage of the 1969 Harlem Cultural Festival.'),
  ('d51bf64f-0c91-5caf-9809-d538d1dd7ec7', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'Which choice completes the text with the most logical and precise word or phrase?', '["authenticated by", "concentrated among", "habituated to", "contemporary with"]'::jsonb, 2, 'Among saltwater fish species, there is a clear association between habitat latitude and morphological variety. While tropical species are ____ deep-bodied physical forms (body shapes that are laterally compressed but vertically extended), polar and temperate species are highly dispersed across the morphological spectrum.'),
  ('d3cd53c0-ed7f-5042-acf8-66ff91aa54dd', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'As used in the text, what does the word "reserve" most nearly mean?', '["Misgiving", "Constraint", "Composure", "Modesty"]'::jsonb, 3, 'The following text is adapted from Edith Wharton’s 1911 novella Ethan Frome. The narrator has asked the woman he rents a room from about Ethan Frome, a town resident he encountered recently.

Her mind was a store-house of innocuous anecdote and any question about her acquaintances brought forth a volume of detail; but on the subject of Ethan Frome I found her unexpectedly reticent. There was no hint of disapproval in her <u>reserve</u>; I merely felt in her an insurmountable reluctance to speak of him.'),
  ('0b28faac-1c0a-5052-b6a2-6c856016c14e', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'Which choice completes the text with the most logical and precise word or phrase?', '["ambivalent", "retrospective", "counterfactual", "analogical"]'::jsonb, 4, 'The work of Tobias Gerstenberg et al. on tracking eye movements supports a theory that people envision _____ scenarios when making causal judgments: when subjects were asked to look at two colliding billiard balls and judge whether one caused or prevented the other’s movement through a gate, their eyes looked at where the target ball would have gone if the ball that altered its path did not exist.'),
  ('04b61da0-dc7e-5e3d-bf7b-7605254c5311', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'Which choice best describes the overall structure of the text?', '["It distinguishes a work from others in its genre, outlines the central objective of that work, and then addresses a recent resurgence of interest in that work.", "It sketches the development of a prominent work, familiarizes readers with an argument in that work, and then suggests that the work has had repercussions in other fields.", "It characterizes a work as having been underappreciated, describes a core concept in that work, and then argues that the influence of that concept is recognizable in other works.", "It introduces a significant work, summarizes a noteworthy idea in that work, and then places that idea into a context that demonstrates its broader implications."]'::jsonb, 5, 'Paul Linebarger is often recognized as an influential science fiction writer (under the pen name Cordwainer Smith), but his most significant work was a 1940s classified US Army guide exploring the role of propaganda in times of war. Citing the uniquely absorbing nature of motion pictures, he contended that US propaganda should equal popular films in its appeal, entertaining audiences while engendering views of the nation as an ally. Linebarger’s work shaped the distinctive US approach to promoting national interests, one that continues to draw inspiration from elements of pop culture.'),
  ('ad3886d3-99b7-59ee-9c61-7d3a328e7608', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'Based on the texts, how would the author of Text 2 most likely respond to the characterization of Meng and colleagues’ study in Text 1?', '["By asserting that the author of Text 1 has overstated the effectiveness of the method that Meng and colleagues used", "By pointing out that the author of Text 1 has overlooked studies that reported results that contradict those reported by Meng and colleagues", "By claiming that the author of Text 1 has misrepresented what Meng and colleagues were trying to achieve with their experimental design", "By arguing that the author of Text 1 has conflated the method used by Meng and colleagues with that used by He and colleagues"]'::jsonb, 6, '**Text 1**

In separate studies, Lingbo Meng and colleagues and Xinhua He and colleagues examined whether plants transfer nutrients to one another using a common mycorrhizal network (CMN)—a lattice of fungal strands in the soil. Meng and colleagues excluded all pathways other than the CMN by using barriers to keep the plants’ root systems separate while allowing mycorrhizal strands through—a crucial step He and colleagues’ study did not take.

**Text 2**

Meng and colleagues took the necessary precaution of separating the plants’ root systems (thereby excluding root-to-root transmission). However, any barrier used must allow the thread-like hyphae of a CMN to pass through, and this permeability would also allow liquids through. Thus, the researchers’ experimental design cannot ensure that any nutrient transfer observed can be attributed to a CMN and not to some other pathway.'),
  ('7ff16012-436b-51d7-8337-14fd5ce57950', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'As presented in the text, Wade would most likely agree with which statement about the first booklet of the Heege Manuscript?', '["It was likely a copy Heege intended to give to a traveling minstrel working in the area around Radford and Brackonwet.", "The texts it includes were based on stories about the area around Radford and Brackonwet, but these names were later removed.", "It was copied from a text that originated from a traveling minstrel who worked in the area around Radford and Brackonwet.", "It was written down by Heege from memory based on a performance by a traveling minstrel who worked in the area around Radford and Brackonwet."]'::jsonb, 7, 'The fifteenth-century English Heege Manuscript is unusual among collections of its kind and time given its focus on fantasy tales over more acclaimed works by celebrated medieval authors like Hoccleve. But according to professor James Wade, even more unusually, the three texts in the manuscript’s first booklet were likely copied by Richard Heege from a traveling minstrel’s repertoire book. The evidence includes performative elements such as the narrator politely addressing the audience, joking about peasants and royalty, and making jokes that could be modified to refer to the town of Radford when in nearby Brackonwet to avoid giving offense.'),
  ('7b33ce1c-b6b2-538d-8134-cb4750080cec', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'Based on the text, which choice best describes the relationship between doing philosophy and studying philosophy?', '["Doing philosophy involves developing novel ideas through imagined dialogue with past philosophers based on knowledge of those philosophers’ views acquired by studying philosophy.", "Doing philosophy helps students formulate concrete solutions to practical issues, whereas studying philosophy prioritizes engagement with historical arguments in the field.", "Doing philosophy represents a departure from the norms that govern scholarly inquiry, whereas studying philosophy requires conformation to these norms.", "Doing philosophy requires students to challenge the ideas articulated by past philosophers, especially when these ideas are broadly accepted by other people studying philosophy."]'::jsonb, 8, 'Within higher education, studying philosophy requires that students be conversant with the field’s foundational texts and historical figures. By contrast, doing philosophy within or beyond the academy demands the creative, self-directed application of acquired expertise to enduring questions about the nature of existence and knowledge. While both approaches engage with influential figures, those who do philosophy treat such figures as vital interlocutors who facilitate new insights rather than as ossified authorities who, though relevant to the present, primarily represent the discipline’s past.'),
  ('488571d7-d1be-56af-8c31-7a504f742548', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'Which finding, if true, would directly weaken the conclusion about Wang and her colleagues’ findings that is presented in the text?', '["Other types of artifacts originating in South Asia and dating to the first through sixth centuries CE have been found throughout Southeast Asia.", "In the first through third centuries CE, there was a significant migration of people from South Asia to Southeast Asia.", "The people of Óc Eo and several communities in South Asia regularly traded with people in the region that is now the Southeast Asian country of Malaysia no later than the first century CE.", "Some of the spices recovered from Óc Eo are native to the Maluku Islands, which are located approximately 2,000 miles southeast of Óc Eo."]'::jsonb, 9, 'Archaeologist Weiwei Wang and her colleagues analyzed footed grinding slabs and other food-preparation tools excavated from Óc Eo, a Southeast Asian port city that flourished between the first and sixth centuries CE. Wang and colleagues recovered microscopic remnants of turmeric and other spices from the surfaces of the tools. Turmeric is native to South Asia, more than a thousand miles west of Óc Eo, and the researchers showed that the footed grinding slabs at Óc Eo are very similar to footed grinding slabs common throughout South Asia from around 500 BCE to 300 CE. Wang and colleagues’ findings therefore indicate that there must have been a trade link, whether direct or indirect, between the two regions.'),
  ('9923c8ee-446d-5ef3-9520-da480a2d3741', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'Which choice most effectively uses data from the table to complete the statement?', '["mammalian fossil evidence offers less dating precision than do 87Sr/86Sr ratios in fossil shark teeth and that PFBV likely was deposited closer to the Hh3-Hh4 boundary than was MFS.", "the average 87Sr/86Sr ratios in the fossil shark teeth from MFS and PFBV resolve previous uncertainty about the sites’ relative ages by indicating that both sites were deposited contemporaneously during the late Hh.", "the average 87Sr/86Sr ratios in the fossil shark teeth from MFS and PFBV only partially support the site age estimates previously established through mammalian fossil evidence.", "the average 87Sr/86Sr ratios in the fossil shark teeth from MFS and PFBV corroborate that both MFS and PFBV fall within Hh4 but suggest that PFBV was likely deposited more recently than MFS."]'::jsonb, 10, '**Table 1**

| 87Sr/86Sr | Numerical Age (Ma) |
| 0.708980 | 6.20 |
| 0.709000 | 5.86 |
| 0.709020 | 5.40 |
| 0.709040 | 4.75 |
| 0.709060 | 3.00 |

The late Hemphillian (Hh) North American Land Mammal Age includes the subdivisions Hh3, 6.8 million years ago (Ma) to 6 Ma, and Hh4, 6 Ma to 4.75 Ma. While mammalian fossils have indicated that Florida’s Montbrook Fossil Site (MFS) and Palmetto Fauna of the Bone Valley Region (PFBV) date to Hh4, a more precise determination of the sites’ ages has proved challenging. Stephanie R. Killingsworth et al. compared average ratios of strontium-87 to strontium-86 (87Sr/86Sr) in fossil shark teeth from MFS and PFBV—0.709000 and 0.709028, respectively—to 87Sr/86Sr ratios in the global strontium seawater curve, a record that shows how 87Sr/86Sr ratios in seawater correspond to numerical ages and that is used to date fossils and, by extension, fossil sites. The researchers concluded that _____'),
  ('aaa773ee-0878-530f-8a94-f98427b9bbd0', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'Which choice most effectively uses data from the graph to illustrate the researchers’ conclusion?', '["Under the assumption that preferences are more salient than density, the US 2 and CI 2 proportions were predicted to be approximately 0.45 and 0.35, respectively, both below the measured values, whereas under the other assumption, the model overestimated the proportion for US 2 and overestimated that for CI 2.", "Under the assumption that preferences are more salient than density, the US 2 and CI 2 proportions were predicted to be in the range of 0.3 to 0.5, placing them farther from the measured values than were those predicted under the other assumption.", "Under the assumption that density is more salient than preferences, the US 2 proportion was predicted to be higher than the measured value, while the CI 2 proportion was predicted to be lower than the measured value.", "Under the assumption that preferences are more salient than density, the CI 2 proportion was predicted to be much closer to the measured value than the US 2 proportion was."]'::jsonb, 11, '![figure](/q/mar26/001.webp)

Researchers used anonymized location data from the US and Côte d’Ivoire to document people’s daily patterns of mobility, using these results to test the efficacy of the researchers’ predictive computer model. In each country, unidirectional cycles among two, three, or four locations were empirically the most common pattern types; the graph shows each of these pattern types as a proportion of all pattern instances found for that country (e.g., the measured value for CI 3 in the graph represents the observed frequency of three-location cycles in Côte d’Ivoire). The researchers compared two different versions of their model: one that emphasized population density as the primary driver of mobility and another that emphasized individual preferences. After analyzing the results, the researchers concluded that the model emphasizing density was significantly more accurate at predicting the most common mobility patterns than the model emphasizing preferences.'),
  ('4eb38b28-1a43-5e6f-aa98-8a057cfba93f', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'Which choice most logically completes the text?', '["encourage consumers to expect next-day delivery only for products that are widely available.", "continue to struggle with last-mile delivery operations until viable solutions become available.", "be able to meet consumer’s expectations for next-day delivery in many areas but not in all regions.", "have little incentive to find a solution to last-mile delivery challenges."]'::jsonb, 12, 'Last-mile delivery refers to the final step in delivering packages to customers—and this final step can be very difficult. Delivery companies are contending with the increasing popularity of next-day delivery and with the increasing volume of parcels to be delivered, resulting in a growing bottleneck of packages in the last-mile delivery stage. These companies have been experimenting with innovative solutions in last-mile delivery, including self-service lockers (containers where consumers can pick up their parcels using a unique code). Unfortunately, many of these innovations create new obstacles (e.g., convenient placement of self-service lockers is challenging) and are not ready for full-scale implementation. As a result, delivery companies will likely _____'),
  ('54122b2d-7094-561a-bae8-19d9d8d6274a', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'Which choice most logically completes the text?', '["social learning and resource fluctuations may both play a role in dietary mix among females, at least temporarily, though genetic factors appear to make a significant contribution as well.", "female dietary mix is best understood as changeable and contingent on fluctuating environmental conditions rather than as the result of social learning or genetic factors.", "dietary mix among females may reflect a social learning effect that eventually diminishes, though environmental constraints cannot be ruled out as a contributing factor.", "growing dissimilarity between mothers and their daughters"]'::jsonb, 13, 'Across brown bears—omnivores with high dietary plasticity—there is wide variety in dietary mix, which may reflect genetics, local resource availability, or social learning (cubs stay with their mothers for two years or more). Evaluating these possibilities, Anne Hertel et al. analyzed 30 years of data on trophic position (indicative of dietary mix) for female brown bears. After separation, daughters, who tended to settle near their mothers, occupied the same trophic positions as their mothers for two years, but the correlation disappeared by year five. Trophic correlation with unrelated individuals in similar habitats was modest, while habitat-independent correlation with nonmaternal relatives (e.g., cousins) was no different than with unrelated individuals. These findings suggest that _____'),
  ('61c1319a-90fe-5308-bf04-123d31c2f1e4', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["they’re", "it’s", "their", "its"]'::jsonb, 14, 'The parks of Los Angeles, California, seem to be making people happier. In a 2022 study, researchers studying connections between the physical location in which a social media post was created and ___ contents analyzed geotagged social media posts from Los Angeles. They found that posts from the city’s parks contained more words associated with happiness than other posts did.'),
  ('bcfbf57b-38f8-59c8-9ef9-ca5af409fe1a', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["STS-51-D, it lasted", "STS-51-D, lasting", "STS-51-D lasting", "STS-51-D. Lasting"]'::jsonb, 15, 'On April 12, 1985, the space shuttle Discovery blasted off into space, commencing Mission _____ six days and twenty-three hours, the mission ended when the shuttle landed at Kennedy Space Center in Florida.'),
  ('bf3f6a9f-4682-54db-a137-cc22bb738284', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["revealing", "reveal", "reveals", "has revealed"]'::jsonb, 16, 'Now seen as a mechanical precursor to the e-reader, Spanish educator and inventor Ángela Ruiz Robles’s Enciclopedia Mecánica eschewed pages in favor of three horizontal paper scrolls that could be easily swapped out to accommodate a range of subjects. Though Ruiz Robles’s prototype had limited functionality, interactive features described in her 1949 patent—such as a button labeled “verb” that would illuminate relevant text when pressed—_____ an impressive early vision of hypertext.'),
  ('a5a6a311-e9ab-5c47-bdb5-be772a3ffe0b', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["novel’s protagonists’", "novels’ protagonists", "novels’ protagonists’", "novel’s protagonist’s"]'::jsonb, 17, 'Jane Austen’s Northanger Abbey (1818) is considered a satire of another novel popular at the time: Ann Radcliffe’s The Mysteries of Udolpho (1794), which Austen’s heroine, Catherine Morland, is depicted reading. However, the similarity of the _____ experiences—the predicaments of both Catherine and Radcliffe’s Emily St. Aubert result from men’s greed—suggests that underlying the satire is a social critique.'),
  ('35ddd55a-dc4c-5bdb-bb27-088760aa82e6', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["time was", "time,", "time had been", "time, was"]'::jsonb, 18, 'Roger Angell’s reputation as one of the greatest baseball writers of all ___ bolstered by dozens of New Yorker essays in which he demonstrated a deep affection for and knowledge of the game, has perhaps overshadowed his remarkable career as a fiction editor: during his decades-long tenure at the New Yorker, Angell helped shape the work of John Updike, Ann Beattie, and other contributors of note.'),
  ('c5311608-0874-5a18-b09a-49bcc403b4d3', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["1890, for example;", "1890, for example,", "1890; for example,", "1890, for example:"]'::jsonb, 19, 'Before the ratification of the 19th Amendment in 1920, many US territories extended voting rights to women, in part to spur westward migration that would help these territories meet population thresholds for statehood. The Territory of Wyoming approved women’s suffrage in 1869 before attaining statehood in ___ while eastern states, lacking the same incentive, did not follow suit until after the turn of the century.'),
  ('1a34fccd-8838-5151-90ac-2dc82dda1b98', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["1648 and", "1648:", "1648;", "1648"]'::jsonb, 20, 'The legacy of the Spanish Empire, which once controlled portions of five continents, is evident in Spanish-speaking Panama, one of many places that reveal their imperial history in their language. Contrast Panama with the Netherlands, which ceased to be part of the empire in _____ the latter’s connection to the empire is so attenuated that Spanish is seldom spoken there today.'),
  ('055f0609-b0fb-5f15-8866-b94496e25d1a', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'Which choice completes the text with the most logical transition?', '["In addition,", "By comparison,", "Similarly,", "Ultimately,"]'::jsonb, 21, 'To determine the approximate age of stone tools excavated from ancient lake beds in Saudi Arabia, archaeologist Eleanor Scerri and colleagues collected samples of sediments surrounding the tools; these samples were then analyzed using a method known as optically stimulated luminescence (OSL) dating. ___ OSL dating indicated that the tools were around 400,000 years old.'),
  ('5befc957-3916-559d-80d9-40c2b9ef3e23', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'Which choice completes the text with the most logical transition?', '["Likewise,", "Next,", "Thus,", "However,"]'::jsonb, 22, 'The moon Lysithea orbits Jupiter in the same direction that the planet rotates. _____ Lysithea’s orbit is described as prograde. Mneme, another of Jupiter’s moons, orbits in the opposite direction, so its orbit is described with the opposite term: retrograde.'),
  ('ade8f938-003c-593b-a1f5-4cf522aca30b', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'Which choice completes the text with the most logical transition?', '["Similarly,", "Secondly,", "By contrast,", "Therefore,"]'::jsonb, 23, 'Macarena Garcia Marin is a space scientist who works on the James Webb Space Telescope, or JWST. Thanks in part to Garcia Marin’s contributions, the telescope is now positioned near the Sun-Earth L2

Lagrange point, almost one million miles beyond Earth’s orbit. ___ the JWST’s predecessor, the Hubble Telescope, is only about 340 miles above Earth’s surface.'),
  ('3ca89da5-5943-5ef7-8ada-8f00c7dacb90', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'Which choice completes the text with the most logical transition?', '["Nonetheless,", "In addition,", "Meanwhile,", "Specifically,"]'::jsonb, 24, 'The Austronesian language of Nauruan has only about 10,300 living speakers. Although most Nauruan speakers live in Nauru, where the language originated, Nauruan is also spoken in New York City. ______ the New York–based Endangered Language Alliance has identified a group of Nauruan speakers in the city’s Murray Hill neighborhood, in the borough of Manhattan.'),
  ('f6e7175b-4615-50c8-8059-5618cc3a8dfc', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'Which choice completes the text with the most logical transition?', '["Furthermore,", "Similarly,", "Still,", "In other words,"]'::jsonb, 25, 'Nineteenth-century Modernista architects championed nature in their designs. Granted, the wavy stone façade and ornate floral tilework of Casa Batlló, a Modernista private home designed by Antoni Gaudí, couldn’t exactly grow in a forest. _____ one sees natural influences in Gaudí’s penchant for curves (rather than right angles) and plant- and animal-inspired flourishes.'),
  ('b13488d3-eb4e-55d0-ab26-891421c8b02d', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'The student wants to explain whom the award is named for and identify one recipient of it. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["In 2008, Barbara Liskov won the A.M. Turing Award, which is given for “major contributions of lasting importance to computing.”", "The A.M. Turing Award, which is named for British mathematician Alan Turing, was given to Barbara Liskov in 2008.", "The A.M. Turing Award is given for “major contributions of lasting importance to computing.”", "It was in 2008 that Barbara Liskov won the A.M. Turing Award, a prestigious award given by the Association for Computing Machinery (ACM)."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

The A.M. Turing Award is a prestigious award given by the Association for Computing Machinery (ACM).
The ACM gives the award for “major contributions of lasting importance to computing.” It is named after groundbreaking British mathematician Alan Turing.
Barbara Liskov won the award in 2008.'),
  ('d1c3a6ba-14a7-52fa-8328-a770208039e6', 'cb1bf05e-7f3d-52f7-9b8b-57363ec8f8ea', 'The student wants to emphasize a specific wavelength in titanium’s emission spectrum and identify its position within the visible spectrum. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The 583.2 nm wavelength, which is in the violet portion of the visible spectrum, is one wavelength in the emission spectrum of krypton.", "Since the 430.5 nm wavelength of light is within the 380–450 nm range, it is part of the violet portion of the visible spectrum.", "Containing the 430.5 nm and 583.2 nm wavelengths, respectively, both titanium’s and krypton’s emission spectra include wavelengths in the violet portion of the visible spectrum.", "Titanium’s emission spectrum includes the 430.5 nm wavelength, which is in the violet portion of the visible spectrum."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

When the electrons of a chemical element change energy states, certain wavelengths of light are released.
This unique collection of wavelengths is known as the emission spectrum of the element. Titanium’s emission spectrum includes the 430.5 nanometer (nm) wavelength.
Krypton’s emission spectrum includes the 583.2 nm wavelength.
The violet portion of the visible spectrum is made up of light with wavelengths of 380–450 nm.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('216c48b9-2ee6-547e-a967-70e4ee569e8c', 3, null, '"Stories without any depth" describes documentaries made carelessly, just to get done: "perfunctory."'),
  ('d51bf64f-0c91-5caf-9809-d538d1dd7ec7', 1, null, 'Tropical species cluster in one body type, unlike the widely spread polar species: "concentrated among."'),
  ('d3cd53c0-ed7f-5042-acf8-66ff91aa54dd', 1, null, 'Her "reticence" and "reluctance to speak" are a holding back: "constraint."'),
  ('0b28faac-1c0a-5052-b6a2-6c856016c14e', 2, null, 'Subjects pictured what would have happened without the other ball: "counterfactual" scenarios.'),
  ('04b61da0-dc7e-5e3d-bf7b-7605254c5311', 3, null, 'It introduces Linebarger''s guide, summarizes its key idea, and then shows its lasting influence on US policy.'),
  ('ad3886d3-99b7-59ee-9c61-7d3a328e7608', 0, null, 'Text 2 says the barrier also let liquids through, so the method was not as airtight as Text 1 suggests.'),
  ('7ff16012-436b-51d7-8337-14fd5ce57950', 2, null, 'Wade thinks the texts were copied from a minstrel''s repertoire book used around Radford and Brackonwet.'),
  ('7b33ce1c-b6b2-538d-8134-cb4750080cec', 0, null, 'Doing philosophy uses knowledge gained by studying past thinkers as "interlocutors" for new insights.'),
  ('488571d7-d1be-56af-8c31-7a504f742548', 1, null, 'South Asian migrants could have brought turmeric and grinding-slab styles without any trade link.'),
  ('9923c8ee-446d-5ef3-9520-da480a2d3741', 3, null, 'MFS (0.709000) dates to about 5.86 Ma and PFBV (0.709028) to about 5.1 Ma: both in Hh4, with PFBV younger.'),
  ('aaa773ee-0878-530f-8a94-f98427b9bbd0', 1, null, 'Showing the preference model''s predictions were farther from the measured values than the density model''s supports the conclusion.'),
  ('4eb38b28-1a43-5e6f-aa98-8a057cfba93f', 1, null, 'Bottlenecks keep growing and innovations aren''t ready yet, so the struggle will likely continue.'),
  ('54122b2d-7094-561a-bae8-19d9d8d6274a', 2, null, 'The mother-daughter match fades by year five (social learning that diminishes), and the habitat correlation means environment may matter; relatives show no genetic effect.'),
  ('61c1319a-90fe-5308-bf04-123d31c2f1e4', 3, null, 'The antecedent is a singular post: "its contents."'),
  ('bcfbf57b-38f8-59c8-9ef9-ca5af409fe1a', 1, null, '"lasting six days..." is a participial phrase attached with a comma.'),
  ('bf3f6a9f-4682-54db-a137-cc22bb738284', 1, null, 'The plural subject "features" takes "reveal."'),
  ('a5a6a311-e9ab-5c47-bdb5-be772a3ffe0b', 2, null, 'Plural possessive "novels''" and plural possessive "protagonists''" (their experiences).'),
  ('35ddd55a-dc4c-5bdb-bb27-088760aa82e6', 1, null, 'The appositive phrase "bolstered by..." is set off by a comma before the verb "has... overshadowed."'),
  ('c5311608-0874-5a18-b09a-49bcc403b4d3', 1, null, '"for example" is set off by commas and the "while" clause continues the sentence.'),
  ('1a34fccd-8838-5151-90ac-2dc82dda1b98', 1, null, 'A colon introduces the explanation of the contrast between Panama and the Netherlands.'),
  ('055f0609-b0fb-5f15-8866-b94496e25d1a', 3, null, 'After sampling and analysis came the final result: "Ultimately."'),
  ('5befc957-3916-559d-80d9-40c2b9ef3e23', 2, null, 'Because it orbits in the planet''s direction, it is called prograde: "Thus."'),
  ('ade8f938-003c-593b-a1f5-4cf522aca30b', 2, null, 'A million miles away vs only 340 miles: "By contrast."'),
  ('3ca89da5-5943-5ef7-8ada-8f00c7dacb90', 3, null, 'The sentence gives the specific New York neighborhood: "Specifically."'),
  ('f6e7175b-4615-50c8-8059-5618cc3a8dfc', 2, null, 'Despite the concession, natural influences are still visible: "Still."'),
  ('b13488d3-eb4e-55d0-ab26-891421c8b02d', 1, null, 'It gives both the namesake (Alan Turing) and a recipient (Barbara Liskov).'),
  ('d1c3a6ba-14a7-52fa-8328-a770208039e6', 3, null, 'It names titanium''s 430.5 nm wavelength and places it in the violet range.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

