insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('f30b20b3-cfc3-5e9e-957d-49347a424b94', '17f7bf5b-534a-57a7-850f-17d4cbc5c07a', 'The function $w$ models the weight, in ounces, of the remaining solid wax of a burning candle as a function of the time $x$, in hours, after the candle was lit. The graph of $y = w(x)$ is shown. According to the model, what was the weight, in ounces, of the candle’s remaining solid wax 12 hours after the candle was lit?', '["$4$", "$8$", "$10$", "$13$"]'::jsonb, 1, '![figure](/q/mar26/002.webp)'),
  ('498dfaf5-7f09-5887-94cf-7bd786cde4b5', '17f7bf5b-534a-57a7-850f-17d4cbc5c07a', 'In $\triangle ABC$, the sum of the measures of $\angle A$ and $\angle B$ is $159.5°$. What is the measure of $\angle C$?', '["$20.5°$", "$90°$", "$110.5°$", "$180°$"]'::jsonb, 2, null),
  ('8f49e7ef-8a04-5596-b886-82b1b06957a0', '17f7bf5b-534a-57a7-850f-17d4cbc5c07a', 'A local gym is offering a $25%$ discount on an annual membership. The regular cost of an annual membership is \$288. How much less is the discounted cost of the membership than the regular cost of the membership?', '["\\$25", "\\$72", "\\$216", "\\$288"]'::jsonb, 3, null),
  ('ee6f7a15-d3f8-5298-86a9-3f4c2ecfaa58', '17f7bf5b-534a-57a7-850f-17d4cbc5c07a', 'The product of a positive number $x$ and the number that is $5$ less than $x$ is equal to $104$. What is the value of $x$?', '["2.5", "13", "99", "109"]'::jsonb, 4, null),
  ('1f9554ec-34e4-5df5-a2c8-4bd904f053f9', '17f7bf5b-534a-57a7-850f-17d4cbc5c07a', 'The table shows three values of $x$ and their corresponding values of $y$. There is a linear relationship between $x$ and $y$. Which of the following equations represents this relationship?', '["y = 8x", "y = 10x + 2", "y = 10x", "y = x + 8"]'::jsonb, 5, '| x | y |
| 0 | 8 |
| 1 | 9 |
| 2 | 10 |'),
  ('f2dc9e36-c3b6-576f-925e-3d2c3b8c7803', '17f7bf5b-534a-57a7-850f-17d4cbc5c07a', 'The function $f$ is defined by the equation $f(x) = 380x$. What is the value of $f(10)$?', '[]'::jsonb, 6, null),
  ('87928599-7fce-5f00-80f3-18436e7b9ad6', '17f7bf5b-534a-57a7-850f-17d4cbc5c07a', 'Which of the following equations has solutions $13$ and $-24$?', '["$(x - 13)(x + 24) = 0$", "$x - 13x + 24 = 0$", "$x + 13x + 24 = 0$", "$x - 24x - 13 = 0$"]'::jsonb, 7, null),
  ('575a5345-5661-585e-b5e0-6ea800b9cc48', '17f7bf5b-534a-57a7-850f-17d4cbc5c07a', 'The scatterplot shows the relationship between two variables, $t$ and $d$. A line of best fit for the data is also shown. Which of the following equations is the most appropriate linear model for the data shown?', '["$d = -60.1 + 2.02t$", "$d = 160.1 + 2.02t$", "$d = 359.8 + 2.02t$", "$d = 394.8 + 2.02t$"]'::jsonb, 8, '![figure](/q/mar26/003.webp)'),
  ('7b964b0b-a9b9-5a85-953e-1ba71fb59192', '17f7bf5b-534a-57a7-850f-17d4cbc5c07a', 'Which ordered pair $x,y$ is a solution to the given system of equations?
$y = 0$
$y = 4x^{2} - 36$', '["$(0,6)$", "$(0,36)$", "$(3,0)$", "$(36,0)$"]'::jsonb, 9, null),
  ('15c57312-6964-59af-b893-d49c6e404a61', '17f7bf5b-534a-57a7-850f-17d4cbc5c07a', 'When a scientist began observing a sample of an isotope, the mass of the sample was $530,000$ milligrams. The mass of the sample decreases by half approximately every $5$ days. Which of the following is closest to the mass, in milligrams, of the sample $35$ days after the scientist began observing the sample?', '["$4,141$", "$15,143$", "$16,563$", "$75,714$"]'::jsonb, 10, null),
  ('a3bca079-59d6-552f-9c65-c6b0b4b82364', '17f7bf5b-534a-57a7-850f-17d4cbc5c07a', 'The height of a right circular cylinder is 31 inches, and the circumference of its base is 310 inches. Which expression represents the total surface area, in square inches, of the cylinder?', '["$31(310)$", "$\\frac{π\\times 155^{2}}{π} \\times 31$", "$9610 + \\frac{π\\times 155^{2}}{π}$", "$9610 + 2π (\\frac{155}{π})^{2}$"]'::jsonb, 11, null),
  ('2a6abe2e-caa2-5273-a2fc-4b2ff762afe5', '17f7bf5b-534a-57a7-850f-17d4cbc5c07a', 'The function $f(w) = 6w^{2}$ gives the area of a rectangle, in square feet $ft^{2}$, if its width is $w$ ft and its length is 6 times its width. Which of the following is the best interpretation of $f(13) = 1,014$?', '["If the width of the rectangle is $13$ ft, then the area of the rectangle is $1,014ft^{2}$.", "If the width of the rectangle is $13$ ft, then the length of the rectangle is $1,014$ ft.", "If the width of the rectangle is $1,014$ ft, then the length of the rectangle is $13$ ft.", "If the width of the rectangle is $1,014$ ft, then the area of the rectangle is $13ft^{2}$."]'::jsonb, 12, null),
  ('bca078be-982a-51f4-9018-6a28c8e885e8', '17f7bf5b-534a-57a7-850f-17d4cbc5c07a', 'The expression $(3x + 5)(8x - 7)$ can be written in the form $ax^{2} + bx + c$, where $a$, $b$, and $c$ are constants. What is the value of $a + b$?', '[]'::jsonb, 13, null),
  ('7c55dbae-25d5-5451-9001-d0e321ead0b3', '17f7bf5b-534a-57a7-850f-17d4cbc5c07a', 'The ratio $a$ to $b$ is equivalent to the ratio $49$ to $26$. What is the value of $a$ when $b = 182$?', '[]'::jsonb, 14, null),
  ('954dc53e-cbf1-565e-ad46-3bfd98d9a38a', '17f7bf5b-534a-57a7-850f-17d4cbc5c07a', 'At the beginning of the year, Imani has $170$ in her account. Each month this year, she will deposit between $30$ and $60$ into the account. Which inequality represents all possibilities for the total amount of money $x$, in dollars, in Imani’s account after 10 months of deposits this year?', '["$x \\le 300$", "$x \\ge 600$", "$170 \\le x \\le 620$", "$470 \\le x \\le 770$"]'::jsonb, 15, null),
  ('45d7c569-9234-53c7-a709-eac44b2215eb', '17f7bf5b-534a-57a7-850f-17d4cbc5c07a', 'The function $f$ is defined by $f(x) = x - 2x - 8x + 3$. In the $xy$-plane, the graph of $y = hx$ is the result of translating the graph of $y = f(x)$ up $6$ units. What is the $y$-coordinate of the $y$-intercept of the graph of $y = hx$?', '["$9$", "$48$", "$6$", "$0$"]'::jsonb, 16, null),
  ('7c075226-8098-5d81-97bb-460d7edc3954', '17f7bf5b-534a-57a7-850f-17d4cbc5c07a', 'A circle has a circumference of $28π$ centimeters. What is the diameter, in centimeters, of the circle?', '[]'::jsonb, 17, null),
  ('8090392a-fee0-55b0-8af4-dd862cc57c97', '17f7bf5b-534a-57a7-850f-17d4cbc5c07a', 'How many solutions does the equation $35x - 25 = 57x - 5$ have?', '["Exactly one", "Exactly two", "Infinitely many", "Zero"]'::jsonb, 18, null),
  ('85f06792-d7c4-5cb3-8446-38b2abc429c8', '17f7bf5b-534a-57a7-850f-17d4cbc5c07a', 'On January 1, 2000, the population of a town was $26,257$ and on January 1, 2010, the population was $26,858$. The equation $10x + 26,257 = 26,858$ describes this situation. Which of the following is the best interpretation of $x$ in this context?', '["The total increase in population between $2000$ and $2010$", "The projected population of the town $10$ years after $2010$", "The average increase per year of the population between $2000$ and $2010$", "The percentage by which the population of the town increased each year between $2000$ and\n\n$2010$"]'::jsonb, 19, null),
  ('d2985e18-b556-5d07-8c46-dbb7c52733e1', '17f7bf5b-534a-57a7-850f-17d4cbc5c07a', 'For the linear function $f$, $f(-5) = -7$, and the slope of the graph of $y = f(x)$ in the $xy$-plane is $3$. Which equation defines $f$?', '["$f(x) = 3x + 8$", "$f(x) = 3x - 5$", "$f(x) = 3x - 7$", "$f(x) = 3x - 12$"]'::jsonb, 20, null),
  ('52cdb994-d370-5bd7-981e-1611de7cae20', '17f7bf5b-534a-57a7-850f-17d4cbc5c07a', 'In the xy-plane, an equation of circle A is $(x - 2)^{2} + (y - 7)^{2} = 25$. Circle B has the same center as circle A but has a radius that is twice the radius of circle A. Which equation represents circle B?', '["$(x - 2)^{2} + (y - 7)^{2} = 50$", "$(x - 2)^{2} + (y - 7)^{2} = 100$", "$(x - 2)^{2} + (y - 7)^{2} = 250$", "$(x - 2)^{2} + (y - 7)^{2} = 625$"]'::jsonb, 21, null),
  ('0019ac0d-ad39-5d4b-b39d-22067a0f2719', '17f7bf5b-534a-57a7-850f-17d4cbc5c07a', 'On line $k$, the ratio of the distance from $u$ to $0$ and the distance from $u$ to $1$ is $9 : 8$. What is the value of $u$ ?', '[]'::jsonb, 22, null)
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('f30b20b3-cfc3-5e9e-957d-49347a424b94', 2, null, 'At $x = 12$ the graph is at $y = 10$ ounces.'),
  ('498dfaf5-7f09-5887-94cf-7bd786cde4b5', 0, null, '$180 - 159.5 = 20.5$ degrees.'),
  ('8f49e7ef-8a04-5596-b886-82b1b06957a0', 1, null, 'The discount is 25% of \$288 = \$72.'),
  ('ee6f7a15-d3f8-5298-86a9-3f4c2ecfaa58', 1, null, '$x(x - 5) = 104$ gives $(x - 13)(x + 8) = 0$, and $x$ is positive: $13$.'),
  ('1f9554ec-34e4-5df5-a2c8-4bd904f053f9', 3, null, '$y$ starts at 8 and rises by 1 for each 1 in $x$: $y = x + 8$.'),
  ('f2dc9e36-c3b6-576f-925e-3d2c3b8c7803', null, array['3800']::text[], '$f(10) = 380(10) = 3,800$.'),
  ('87928599-7fce-5f00-80f3-18436e7b9ad6', 0, null, '$(x - 13)(x + 24) = 0$ is true when $x = 13$ or $x = -24$.'),
  ('575a5345-5661-585e-b5e0-6ea800b9cc48', 0, null, 'The line passes near $(250, 445)$: $445 - 2.02(250) ≈ -60$, so $d = -60.1 + 2.02t$.'),
  ('7b964b0b-a9b9-5a85-953e-1ba71fb59192', 2, null, '$0 = 4x^{2} - 36$ gives $x = \pm 3$; $(3, 0)$ is listed.'),
  ('15c57312-6964-59af-b893-d49c6e404a61', 0, null, '35 days is 7 half-lives: $\frac{530,000}{2^{7}} ≈ 4,141$.'),
  ('a3bca079-59d6-552f-9c65-c6b0b4b82364', 3, null, '$r = \frac{155}{π}$. Lateral area $310 \cdot 31 = 9,610$ plus two bases $2π(\frac{155}{π})^{2}$.'),
  ('2a6abe2e-caa2-5273-a2fc-4b2ff762afe5', 0, null, '$f(13) = 1,014$: a width of 13 ft gives an area of 1,014 square feet.'),
  ('bca078be-982a-51f4-9018-6a28c8e885e8', null, array['43']::text[], '$(3x + 5)(8x - 7) = 24x^{2} + 19x - 35$, so $a + b = 24 + 19 = 43$.'),
  ('7c55dbae-25d5-5451-9001-d0e321ead0b3', null, array['343']::text[], '$\frac{a}{182} = \frac{49}{26}$, so $a = 49 \cdot 7 = 343$.'),
  ('954dc53e-cbf1-565e-ad46-3bfd98d9a38a', 3, null, 'Ten deposits add between \$300 and \$600 to \$170: $470 \le x \le 770$.'),
  ('45d7c569-9234-53c7-a709-eac44b2215eb', 0, null, '$f(x) = x - 2x - 8x + 3 = -9x + 3$, so $f(0) = 3$ and $h(0) = 3 + 6 = 9$.'),
  ('7c075226-8098-5d81-97bb-460d7edc3954', null, array['28']::text[], 'Circumference $πd = 28π$, so $d = 28$.'),
  ('8090392a-fee0-55b0-8af4-dd862cc57c97', 0, null, '$-22x = 20$ has exactly one solution.'),
  ('85f06792-d7c4-5cb3-8446-38b2abc429c8', 2, null, '$10x$ is the 10-year increase, so $x$ is the average yearly increase.'),
  ('d2985e18-b556-5d07-8c46-dbb7c52733e1', 0, null, '$3(-5) + b = -7$ gives $b = 8$.'),
  ('52cdb994-d370-5bd7-981e-1611de7cae20', 1, null, 'Circle A has radius 5, so circle B has radius 10 and $r^{2} = 100$.'),
  ('0019ac0d-ad39-5d4b-b39d-22067a0f2719', null, array['9/17', '.5294', '0.529', '9']::text[], '$\frac{|u|}{|u - 1|} = \frac{9}{8}$: between 0 and 1, $8u = 9 - 9u$ gives $u = \frac{9}{17}$; beyond 1, $u = 9$.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

