insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('a4a186ac-5f59-58ab-bce4-5820cd3634da', '42de4c97-aa8d-5edb-815b-30b50e161efe', 'A cable company charges new customers a onetime installation fee and a monthly service fee for cable service. The equation $y = 50x + 120$ gives the total amount $y$, in dollars, the cable company charges new customers for $x$ months of cable service. What is the amount, in dollars, of the onetime installation fee the cable company charges new customers?', '["$170$", "$120$", "$70$", "$0$"]'::jsonb, 1, null),
  ('87c0f64e-7bfe-5e31-96b9-b372109ae75c', '42de4c97-aa8d-5edb-815b-30b50e161efe', 'Data set X: $13,16,19,21,24,25,25,26,38$
Data set Y: $13,16,19,21,24,25,25,26,33$
Data set Y is created by replacing the number $38$ in data set X with the number $33$. Which of the following statements is true about the means and medians of data set X and data set Y?', '["The mean of data set X is greater than the mean of data set Y, and the median of data set X equals the median of data set Y.", "The mean of data set X is greater than the mean of data set Y, and the median of data set X is greater than the median of data set Y.", "The mean of data set X equals the mean of data set Y, and the median of data set X equals the median of data set Y.", "The mean of data set X is less than the mean of data set Y, and the median of data set X is greater than the median of data set Y."]'::jsonb, 2, null),
  ('2bb7c47a-d82f-5eba-9283-21352ee2ecc2', '42de4c97-aa8d-5edb-815b-30b50e161efe', '$y = 4x + 36$
One of the two equations in a system of linear equations is given. The system has infinitely many solutions. Which equation could be the second equation in this system?', '["$y - 4x = -36$", "$y - 4x = 36$", "$y - 9x = 18$", "$y - 9x = 0$"]'::jsonb, 3, null),
  ('eca81b75-e81f-566e-a65d-1783e06a7f40', '42de4c97-aa8d-5edb-815b-30b50e161efe', 'If $x + 3y = 29$ and $7x - 12y = -61$, what is the value of $y$?', '[]'::jsonb, 4, null),
  ('b881d100-792f-5122-a74a-564c4a95fb6a', '42de4c97-aa8d-5edb-815b-30b50e161efe', '$R = \frac{0.36l}{A}$
The given equation relates the resistance $R$, in ohms, of a wire to its length $l$, in meters, and its cross-sectional area $A$, in square meters. Which equation correctly expresses the length, in meters, of the wire in terms of its resistance, in ohms, and its cross-sectional area, in square meters?', '["$l = \\frac{R}{0.36}$", "$l = \\frac{R+A}{0.36}$", "$l = \\frac{0.36R}{A}$", "$l = \\frac{AR}{0.36}$"]'::jsonb, 5, null),
  ('07242871-f9ef-5d20-a378-e6533fd3e942', '42de4c97-aa8d-5edb-815b-30b50e161efe', 'For the polynomial function $f$, the graph of $y = f(x)$ in the $xy$-plane passes through the points $(-5,0)$, $(3,0)$, and $(7,0)$. Which of the following must be a factor of $f(x)$?', '["$x + 3$", "$x + 7$", "$x - 3$", "$x - 5$"]'::jsonb, 6, null),
  ('6f6d3343-4daa-5bcb-9b1d-1d1434879d30', '42de4c97-aa8d-5edb-815b-30b50e161efe', 'Which shaded region represents the solutions to the inequality $4x + 5y < 9$?', '["![figure](/q/mar26/004.webp)", "![figure](/q/mar26/005.webp)", "![figure](/q/mar26/006.webp)", "![figure](/q/mar26/007.webp)"]'::jsonb, 7, null),
  ('133fd7ab-f64a-59e0-8782-88f5bce6d9e6', '42de4c97-aa8d-5edb-815b-30b50e161efe', 'In the $xy$-plane, line $k$ has a slope of $\frac{6}{13}$, an $x$-intercept of $(-6,0)$, and a $y$-intercept of $(0,p)$. What is the value of $p$?', '[]'::jsonb, 8, null),
  ('47b25787-70f7-5c39-8990-a357b47af88e', '42de4c97-aa8d-5edb-815b-30b50e161efe', 'The measure of angle $S$ is $\frac{8π}{11}$ radians. The measure of angle $T$ is $2$ times the measure of angle $S$. Which expression represents the measure, in \textbf{degrees}, of angle $T$?', '["$\\frac{8}{11} \\times 90 \\cdot 2$", "$\\frac{8}{11} \\times 180 \\cdot 2$", "$\\frac{8}{11π} \\times 90 \\cdot 2$", "$\\frac{8π}{11} \\times 180 \\cdot 2$"]'::jsonb, 9, null),
  ('2163be94-f98c-5667-8833-6a17cdfe33b8', '42de4c97-aa8d-5edb-815b-30b50e161efe', 'What is the $x$-intercept of the graph of $y = \frac{45-x}{ax+b}$ in the $xy$-plane, where $a$ and $b$ are positive constants?', '["$(-\\frac{b}{a},0)$", "$(0, \\frac{45}{b})$", "$(0,-45)$", "$(45,0)$"]'::jsonb, 10, null),
  ('40c02758-04da-5c0c-b4a1-2d21dbc32acc', '42de4c97-aa8d-5edb-815b-30b50e161efe', 'The ratio $x$ to $y$ is equivalent to the ratio $4$ to $7$. If $x = 11r$, what is the value of $y$ in terms of $r$?', '["$\\frac{4}{77}r$", "$\\frac{7}{44}r$", "$\\frac{44}{7}r$", "$\\frac{77}{4}r$"]'::jsonb, 11, null),
  ('33f3d978-ccea-591d-a8e9-f4e4ee2293c9', '42de4c97-aa8d-5edb-815b-30b50e161efe', '**A research manager selected 2 random samples of ovens of a certain type to estimate the** **average amount of time this type of oven takes to preheat to** $350$ **degrees Fahrenheit** (°F)**. The** **research manager recorded the amount of time, in minutes, each oven takes to preheat to** $350°F$**. Based on the first sample, the research manager estimated that this type of oven takes** **an average of** $14.2$ **minutes to preheat to** $350°F$**, with an associated margin of error of** $1$ **minute.** **Based on the second sample, the research manager estimated that this type of oven takes an** **average of** $14.4$ **minutes to preheat to** $350°F$**, with an associated margin of error of** $2.2$ **minutes.** **Assuming the margins of error were calculated the same way, which of the following best explains** **why the first sample obtained a smaller margin of error than the second sample?**', '["The first sample contained fewer ovens than the second sample.", "The first sample contained more ovens than the second sample.", "The first sample took less time on average to preheat to $350°F$ than the second sample.", "The first sample took more time on average to preheat to $350°F$ than the second sample."]'::jsonb, 12, null),
  ('3be29cc7-d998-5f47-ba5d-706f19c8e3bc', '42de4c97-aa8d-5edb-815b-30b50e161efe', 'The function $f$ is defined by $f(x) = 231(1.20)^{\frac{x}{4}}$. For the given function, the value of $f(x)$ increases by $p%$ for every increase of $x$ by $8$. What is the value of $p$?', '["$20$", "$31$", "$40$", "$44$"]'::jsonb, 13, null),
  ('4fddceb3-a177-54fc-9705-5864711e7429', '42de4c97-aa8d-5edb-815b-30b50e161efe', 'A model estimates that in a particular forest, the number of trees with any given diameter measured at shoulder height is $21%$ less for each 1-inch increase in tree diameter measured at shoulder height. The model can be written in the form $f(x) = ab^{x}$, where $a$ and $b$ are constants and $x$ is the tree’s diameter, in inches, measured at shoulder height, and $x \ge 5$. The model estimates that 3,100 trees in this forest have a diameter of 13 inches measured at shoulder height. Which function best represents this model?', '["$f(x) = 3,100(0.21)^{x}$", "$f(x) = 3,100(0.79)^{x}$", "$f(x) = 66,000(0.21)^{x}$", "$f(x) = 66,000(0.79)^{x}$"]'::jsonb, 14, null),
  ('adff8755-e292-54cc-a5af-c45f614a4948', '42de4c97-aa8d-5edb-815b-30b50e161efe', 'The function $f$ is defined by $f(x) = ax - b$, where $a$ and $b$ are constants. In the $xy$-plane, the graph of $y = f(x)$ passes through the points $(c,11)$ and $(2c,221)$, where $c$ is a constant. Which of the following could be the value of $b$?', '["$199$", "$25$", "$210$", "$232$"]'::jsonb, 15, null),
  ('08e67024-7c1a-5e68-876d-5d069be22b29', '42de4c97-aa8d-5edb-815b-30b50e161efe', 'The price of an item increased by $p%$ from \$90 to \$93. What is the value of $p$?', '[]'::jsonb, 16, null),
  ('495a87b4-9d74-5435-8f97-498e49cfd6bd', '42de4c97-aa8d-5edb-815b-30b50e161efe', 'In triangle $ABC$, the measure of angle $A$ is $56°$ and $AC = 30$. In triangle $PQR$, the measure of angle $P$ is $56°$ and $PR = 90$. Which additional piece of information is sufficient to prove that triangle $ABC$ is similar to triangle $PQR$?', '["$AB = 20$ and $PQ = 20$.", "$AB = 20$ and $QR = 60$.", "The measures of angle $B$ and angle $R$ are $48°$ and $76°$, respectively.", "The measures of angle $B$ and angle $Q$ are $56°$ and $48°$, respectively."]'::jsonb, 17, null),
  ('137189b2-81ce-5e10-9d25-66134be147ab', '42de4c97-aa8d-5edb-815b-30b50e161efe', 'In the equation $(x + 9)(x - \sqrt{5k + 9}) = 0$, $k$ is a positive constant. The product of the solutions to the equation is $-45$. What is the value of $k$?', '[]'::jsonb, 18, null),
  ('9544f1e9-de2b-5217-a6be-e6e64b42599f', '42de4c97-aa8d-5edb-815b-30b50e161efe', 'In the given equation, $p$ and $w$ are integer constants. The equation has exactly one real solution. Which is NOT a possible value of $w$?
$4x^{2} - px + w = -86$', '["$-22$", "$14$", "$25$", "$314$"]'::jsonb, 19, null),
  ('be97250a-e9a4-505b-82b3-42f3eb353943', '42de4c97-aa8d-5edb-815b-30b50e161efe', 'If $\frac{x+6}{5} = \frac{x+6}{13}$, the value of $x + 6$ is between which of the following pairs of values?', '["-7 and -5", "-2 and 2", "2 and 7", "8 and 13"]'::jsonb, 20, null),
  ('e41a1ca1-8e95-5573-a6fe-037dbc9428ed', '42de4c97-aa8d-5edb-815b-30b50e161efe', 'The expression $6x^{4} + 17x^{2} + 5$ can be rewritten as $(3x^{2} + a)(2x^{2} + b)$, where $a$ and $b$ are positive integers, or as $(3x^{2} + c)(2x^{2} + d)$, where $c$ and $d$ are positive nonintegers. What is the value of $a + c$?', '[]'::jsonb, 21, null),
  ('783aacba-2402-56e8-92cd-98ea7a1b1eb3', '42de4c97-aa8d-5edb-815b-30b50e161efe', 'Which of the following equations best represents the line of best fit shown?', '["$y = 9.5 + 0.4x$", "$y = 9.5 - 0.4x$", "$y = -9.5 + 0.4x$", "$y = -9.5 - 0.4x$"]'::jsonb, 22, '![figure](/q/mar26/008.webp)

The scatterplot shows the relationship between two variables, $x$ and $y$. A line of best fit is also shown.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('a4a186ac-5f59-58ab-bce4-5820cd3634da', 1, null, 'The constant term is the one-time charge: \$120.'),
  ('87c0f64e-7bfe-5e31-96b9-b372109ae75c', 0, null, 'Lowering the largest value lowers the mean, but the middle value (24) stays the same.'),
  ('2bb7c47a-d82f-5eba-9283-21352ee2ecc2', 1, null, '$y - 4x = 36$ is the same line as $y = 4x + 36$.'),
  ('eca81b75-e81f-566e-a65d-1783e06a7f40', null, array['8']::text[], '$x = 29 - 3y$; $7(29 - 3y) - 12y = -61$ gives $-33y = -264$, so $y = 8$.'),
  ('b881d100-792f-5122-a74a-564c4a95fb6a', 3, null, '$RA = 0.36l$, so $l = \frac{AR}{0.36}$.'),
  ('07242871-f9ef-5d20-a378-e6533fd3e942', 2, null, 'A zero at $x = 3$ means $x - 3$ is a factor.'),
  ('6f6d3343-4daa-5bcb-9b1d-1d1434879d30', 2, null, '$y < \frac{9 - 4x}{5}$: a dashed boundary with the region below it shaded.'),
  ('133fd7ab-f64a-59e0-8782-88f5bce6d9e6', null, array['36/13', '2.769', '2.77']::text[], 'Through $(-6, 0)$ with slope $\frac{6}{13}$: $p = \frac{6}{13}(6) = \frac{36}{13}$.'),
  ('47b25787-70f7-5c39-8990-a357b47af88e', 1, null, '$T = 2 \cdot \frac{8π}{11}$ radians $= \frac{8}{11} \times 180 \cdot 2$ degrees.'),
  ('2163be94-f98c-5667-8833-6a17cdfe33b8', 3, null, '$y = 0$ when $x = 45$ (the denominator is not zero there).'),
  ('40c02758-04da-5c0c-b4a1-2d21dbc32acc', 3, null, '$y = \frac{7}{4}x = \frac{7}{4}(11r) = \frac{77}{4}r$.'),
  ('33f3d978-ccea-591d-a8e9-f4e4ee2293c9', 1, null, 'A larger sample gives a smaller margin of error.'),
  ('3be29cc7-d998-5f47-ba5d-706f19c8e3bc', 3, null, 'An increase of 8 in $x$ multiplies $f$ by $1.20^{2} = 1.44$: a 44% increase.'),
  ('4fddceb3-a177-54fc-9705-5864711e7429', 3, null, '$b = 0.79$; $a(0.79)^{13} = 3,100$ gives $a ≈ 66,000$.'),
  ('adff8755-e292-54cc-a5af-c45f614a4948', 0, null, '$ac - b = 11$ and $2ac - b = 221$ give $ac = 210$ and $b = 199$.'),
  ('08e67024-7c1a-5e68-876d-5d069be22b29', null, array['10/3', '3.333', '3.33']::text[], '$\frac{93 - 90}{90} = \frac{1}{30} ≈ 3.33\%$, so $p = \frac{10}{3}$.'),
  ('495a87b4-9d74-5435-8f97-498e49cfd6bd', 2, null, 'With $B = 48°$ and $R = 76°$, angle $Q = 48°$, so two pairs of angles match (A with P, B with Q).'),
  ('137189b2-81ce-5e10-9d25-66134be147ab', null, array['16/5', '3.2']::text[], 'The solutions are $-9$ and $\sqrt{5k + 9}$; $-9\sqrt{5k + 9} = -45$ gives $5k + 9 = 25$, so $k = 3.2$.'),
  ('9544f1e9-de2b-5217-a6be-e6e64b42599f', 2, null, 'One solution means $p^{2} = 16(w + 86)$, so $w + 86$ is a perfect square: $-22$, $14$ and $314$ work ($64$, $100$, $400$), but $25$ gives $111$.'),
  ('be97250a-e9a4-505b-82b3-42f3eb353943', 1, null, '$\frac{x + 6}{5} = \frac{x + 6}{13}$ only when $x + 6 = 0$, which lies between $-2$ and $2$.'),
  ('e41a1ca1-8e95-5573-a6fe-037dbc9428ed', null, array['17/2', '8.5']::text[], '$(3x^{2} + 1)(2x^{2} + 5)$ gives $a = 1$; $(3x^{2} + 7.5)(2x^{2} + \frac{2}{3})$ also works, so $c = 7.5$. $a + c = 8.5$.'),
  ('783aacba-2402-56e8-92cd-98ea7a1b1eb3', 1, null, 'The line starts at $y ≈ 9.5$ and falls about 0.4 per unit of $x$.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;
